-- +1 Hit a Ragdoll: asset showcase builder (generated by tools/bundle.py, do not edit)
-- Paste all of this into the Studio command bar (View > Command Bar) and press Enter.
local __modules, __cache = {}, {}
local function __require(name)
	if __cache[name] == nil then __cache[name] = __modules[name]() end
	return __cache[name]
end

