__modules["Builder"] = function()
--[[
	Builder: low-level helpers for the studded blocky style.

	All parts are anchored matte SmoothPlastic in one flat colour, with QM's stud
	texture on every face ("studs"), an Inlet top ("inlet"), or no detail ("smooth"). Positions are given in the local
	space of an origin CFrame, so every asset can be built at any spot and rotation.
]]

local Palette = __require("Palette")

local Builder = {}

-- The grid texture laid over every studded face. It starts as the settings in
-- Palette.Baseplate and is replaced by the place's own Baseplate texture when
-- one exists (Builder.useGridFrom), so blocks get the same native checker grid.
Builder.Grid = {
	Texture = Palette.Baseplate.Texture,
	StudsPerTileU = Palette.Baseplate.StudsPerTile,
	StudsPerTileV = Palette.Baseplate.StudsPerTile,
	Transparency = Palette.Baseplate.TextureTransparency,
	Color3 = Palette.Baseplate.TextureColor,
}

function Builder.useGridFrom(tex: Texture)
	Builder.Grid = {
		Texture = tex.Texture,
		StudsPerTileU = tex.StudsPerTileU,
		StudsPerTileV = tex.StudsPerTileV,
		Transparency = if tex.Transparency >= 1 then Palette.Baseplate.TextureTransparency else tex.Transparency,
		Color3 = tex.Color3,
	}
end

-- QM's L-stud texture (Figma stud tile, same asset FightToStealAnEgg uses for
-- its HUD). Mostly transparent, so the part's own flat colour shows through.
-- One tile is 4x4 studs.
Builder.Studs = {
	Texture = "rbxassetid://100359261064701",
	StudsPerTile = 4,
	-- softens the L shadow so it reads like the reference instead of popping
	Transparency = 0.35,
}

local NORMALS = { Enum.NormalId.Top, Enum.NormalId.Bottom, Enum.NormalId.Left, Enum.NormalId.Right, Enum.NormalId.Front, Enum.NormalId.Back }

function Builder.addGrid(p: BasePart)
	local g = Builder.Grid
	for _, face in NORMALS do
		local t = Instance.new("Texture")
		-- unique names: Rojo can drop siblings that share a name when it syncs
		t.Name = "Grid" .. face.Name
		t.Face = face
		t.Texture = g.Texture
		t.StudsPerTileU = g.StudsPerTileU
		t.StudsPerTileV = g.StudsPerTileV
		t.Transparency = g.Transparency
		t.Color3 = g.Color3
		t.Parent = p
	end
end

function Builder.addStuds(p: BasePart)
	local st = Builder.Studs
	for _, face in NORMALS do
		local t = Instance.new("Texture")
		t.Name = "Studs" .. face.Name
		t.Face = face
		t.Texture = st.Texture
		t.StudsPerTileU = st.StudsPerTile
		t.StudsPerTileV = st.StudsPerTile
		t.Transparency = st.Transparency
		-- the tile's white rim highlight is tinted to the block's own colour, so
		-- only the dark L shadow shows; untinted it glows on dark blocks
		t.Color3 = p.Color
		t.Parent = p
	end
end

local FACES = { "TopSurface", "BottomSurface", "LeftSurface", "RightSurface", "FrontSurface", "BackSurface" }

type Style = "studs" | "inlet" | "smooth"

-- f > 0 lightens towards white, f < 0 darkens towards black.
function Builder.shade(c: Color3, f: number): Color3
	if f >= 0 then
		return c:Lerp(Color3.new(1, 1, 1), f)
	end
	return c:Lerp(Color3.new(0, 0, 0), -f)
end

function Builder.jitter(c: Color3, rng: Random, amount: number): Color3
	return Builder.shade(c, (rng:NextNumber() * 2 - 1) * amount)
end

function Builder.pick(list: { any }, rng: Random): any
	return list[rng:NextInteger(1, #list)]
end

function Builder.model(name: string, parent: Instance?, pivot: CFrame?): Model
	local m = Instance.new("Model")
	m.Name = name
	if pivot then
		m.WorldPivot = pivot
	end
	m.Parent = parent
	return m
end

function Builder.applyStyle(p: BasePart, style: Style?)
	style = style or "studs"
	-- studs come from QM's stud texture, not Roblox's SurfaceType.Studs
	for _, face in FACES do
		(p :: any)[face] = Enum.SurfaceType.Smooth
	end
	if style == "inlet" then
		p.TopSurface = Enum.SurfaceType.Inlet
	end
	-- obstacles are flat colour with studs only (QM): no grid texture, no checker.
	if style == "studs" then
		Builder.addStuds(p)
	end
end

type PartOpts = {
	class: string?,
	name: string?,
	material: Enum.Material?,
	canCollide: boolean?,
	castShadow: boolean?,
	transparency: number?,
}

-- Raw part at a world CFrame.
function Builder.part(parent: Instance, size: Vector3, cf: CFrame, color: Color3, style: Style?, opts: PartOpts?): BasePart
	local o: PartOpts = opts or {}
	local p = Instance.new(o.class or "Part") :: BasePart
	p.Anchored = true
	p.Size = size
	p.CFrame = cf
	p.Color = color
	-- matte everywhere: flat SmoothPlastic with no reflectance
	p.Material = o.material or Enum.Material.SmoothPlastic
	p.Reflectance = 0
	Builder.applyStyle(p, style)
	p.CanCollide = o.canCollide ~= false
	p.CastShadow = o.castShadow ~= false
	if o.transparency then
		p.Transparency = o.transparency
	end
	-- unique sibling names keep Rojo syncs reliable
	p.Name = o.name or ("Block" .. (#parent:GetChildren() + 1))
	p.Parent = parent
	return p
end

-- Part centred at a local position relative to origin.
function Builder.box(parent: Instance, origin: CFrame, center: Vector3, size: Vector3, color: Color3, style: Style?, opts: PartOpts?): BasePart
	return Builder.part(parent, size, origin * CFrame.new(center), color, style, opts)
end

-- Part whose bottom face sits at local y = bottom.
function Builder.block(parent: Instance, origin: CFrame, x: number, bottom: number, z: number, size: Vector3, color: Color3, style: Style?, opts: PartOpts?): BasePart
	return Builder.box(parent, origin, Vector3.new(x, bottom + size.Y / 2, z), size, color, style, opts)
end

-- The texture the default Studio baseplate uses, applied to the top face.
function Builder.baseplateTexture(p: BasePart, settings)
	local t = Instance.new("Texture")
	t.Name = "BaseplateGrid"
	t.Face = Enum.NormalId.Top
	t.Texture = settings.Texture
	t.StudsPerTileU = settings.StudsPerTile
	t.StudsPerTileV = settings.StudsPerTile
	t.Transparency = settings.TextureTransparency
	t.Color3 = settings.TextureColor
	t.Parent = p
	return t
end

-- Floating name tag used by the showcase.
function Builder.label(adornee: Instance, text: string, height: number)
	local gui = Instance.new("BillboardGui")
	gui.Name = "ShowcaseLabel"
	gui.Size = UDim2.fromOffset(220, 40)
	gui.StudsOffsetWorldSpace = Vector3.new(0, height, 0)
	gui.AlwaysOnTop = true
	gui.MaxDistance = 160
	gui.Adornee = adornee
	local tl = Instance.new("TextLabel")
	tl.Size = UDim2.fromScale(1, 1)
	tl.BackgroundTransparency = 1
	tl.Font = Enum.Font.FredokaOne
	tl.TextScaled = true
	tl.TextColor3 = Color3.new(1, 1, 1)
	tl.TextStrokeTransparency = 0
	tl.Text = text
	tl.Parent = gui
	gui.Parent = adornee
	return gui
end

return Builder

end

__modules["Kit"] = function()
--[[
	Kit: palette-driven generators for the ground, walls and trees.

	Each generator takes (parent, origin, palette, opts) and returns a Model whose
	pivot is the origin, sitting on local y = 0. Generators with randomness take
	opts.seed so the same seed always gives the same shape.
]]

local Workspace = game:GetService("Workspace")

local Builder = __require("Builder")
local Palette = __require("Palette")

local Kit = {}

local V3 = Vector3.new
local block = Builder.block
local shade = Builder.shade

local function rngFor(opts): Random
	return Random.new(opts.seed or 1)
end

--------------------------------------------------------------------------------
-- Ground: a clone of the place's own default Baseplate (same part, same native
-- grid texture), with only its colour changed. Top face sits at local y = 0.
-- Falls back to building an identical part if the place has no Baseplate.
--------------------------------------------------------------------------------
function Kit.nativeBaseplate(): BasePart?
	local bp = Workspace:FindFirstChild("Baseplate")
	if bp and bp:IsA("BasePart") then
		return bp
	end
	return nil
end

function Kit.ground(parent, origin: CFrame, pal, opts)
	opts = opts or {}
	local settings = Palette.Baseplate
	local source = opts.source or Kit.nativeBaseplate()
	local nativeTex = source and source:FindFirstChildOfClass("Texture")
	if nativeTex then
		Builder.useGridFrom(nativeTex)
	end
	local p: BasePart
	if source then
		p = source:Clone()
		-- strip anything that is not the native look (scripts, welds, etc.)
		for _, child in p:GetChildren() do
			if not child:IsA("Texture") then
				child:Destroy()
			end
		end
	else
		p = Builder.part(Workspace, V3(512, settings.Thickness, 512), CFrame.new(), pal.Ground, "smooth")
		Builder.baseplateTexture(p, settings)
	end
	-- An earlier showcase script hid the template baseplate; make the copy visible.
	p.Transparency = 0
	p.CanCollide = true
	p.Anchored = true
	p.Locked = false
	p.Material = Enum.Material.Plastic
	p.Reflectance = 0
	for _, tex in p:GetChildren() do
		if tex:IsA("Texture") and tex.Transparency >= 1 then
			tex.Transparency = settings.TextureTransparency
		end
	end
	local thickness = p.Size.Y
	p.Size = V3(opts.sizeX or p.Size.X, thickness, opts.sizeZ or p.Size.Z)
	p.CFrame = origin * CFrame.new(0, -thickness / 2, 0)
	p.Color = opts.color or pal.Ground
	p.TopSurface = Enum.SurfaceType.Smooth -- the ground is the plain native baseplate: grid texture, no studs
	p.Name = opts.name or (pal.Name .. "Baseplate")
	p.Parent = parent
	return p
end

--------------------------------------------------------------------------------
-- Walls: one dirt slab and one grass cap per segment, flat colours with the
-- L-stud texture on every face.
-- opts: length, height, cap (grass thickness), depth,
--       bands (a grass band every bandEvery studs, like the striped cliffs)
--------------------------------------------------------------------------------
local function wallSlab(m, origin: CFrame, pal, x: number, z: number, sx: number, sz: number, opts)
	local height = opts.height or 24
	local cap = opts.cap or 4
	local bandEvery = opts.bands and (opts.bandEvery or 12) or nil
	local y = 0
	while y < height - cap do
		local top = if bandEvery then math.min(y + bandEvery, height - cap) else height - cap
		local isBand = bandEvery ~= nil and top < height - cap
		local dirtTop = if isBand then top - cap else top
		block(m, origin, x, y, z, V3(sx, dirtTop - y, sz), pal.Dirt, "studs")
		if isBand then
			block(m, origin, x, dirtTop, z, V3(sx, cap, sz), pal.Grass, "studs")
		end
		y = top
	end
	block(m, origin, x, height - cap, z, V3(sx, cap, sz), pal.Grass, "studs")
end

function Kit.wall(parent, origin: CFrame, pal, opts)
	opts = opts or {}
	local m = Builder.model(opts.name or "Wall", parent, origin)
	wallSlab(m, origin, pal, 0, 0, opts.length or 32, opts.depth or 4, opts)
	return m
end

-- L-shaped corner: one arm along +X, one along +Z, meeting at the origin.
function Kit.wallCorner(parent, origin: CFrame, pal, opts)
	opts = opts or {}
	local len = opts.length or 16
	local depth = opts.depth or 4
	local m = Builder.model(opts.name or "WallCorner", parent, origin)
	wallSlab(m, origin, pal, (len + depth) / 2 - depth / 2, 0, len + depth, depth, opts)
	wallSlab(m, origin, pal, 0, depth / 2 + len / 2, depth, len, opts)
	return m
end

--------------------------------------------------------------------------------
-- Cliff: one raised block of land, like the stepped plateaus in the reference.
-- Dirt body with a darker band at the foot and a grass cap, bottom at local y = 0.
-- opts: sizeX, sizeZ, height, cap, name
--------------------------------------------------------------------------------
function Kit.cliff(parent, origin: CFrame, pal, opts)
	opts = opts or {}
	local sx, sz = opts.sizeX or 24, opts.sizeZ or 24
	local height = opts.height or 12
	local cap = math.min(opts.cap or 4, height - 2)
	local m = Builder.model(opts.name or "Cliff", parent, origin)
	local foot = math.min(2, height - cap - 1)
	if foot > 0 then
		block(m, origin, 0, 0, 0, V3(sx, foot, sz), pal.Dirt, "studs")
	end
	block(m, origin, 0, math.max(foot, 0), 0, V3(sx, height - cap - math.max(foot, 0), sz), pal.Dirt, "studs")
	block(m, origin, 0, height - cap, 0, V3(sx, cap, sz), pal.Grass, "studs")
	return m
end

-- Low leafy bush sitting on the ground.
function Kit.bush(parent, origin: CFrame, pal, opts)
	opts = opts or {}
	local m = Builder.model(opts.name or "Bush", parent, origin)
	local rng = rngFor(opts)
	local w = opts.width or 6
	local c = Builder.pick(pal.Leaves, rng)
	block(m, origin, 0, 0, 0, V3(w, 3, w), c, "studs")
	block(m, origin, (rng:NextNumber() - 0.5) * 2, 3, (rng:NextNumber() - 0.5) * 2, V3(math.max(2, w - 2) + 0.02, 2, math.max(2, w - 2) + 0.02), c, "studs")
	return m
end

--------------------------------------------------------------------------------
-- Leaf cluster: stacked, offset studded boxes. Bottom of the cluster at local y=0.
--------------------------------------------------------------------------------
function Kit.canopy(m, origin: CFrame, pal, rng: Random, width: number)
	local idx = 0
	local function leaf(cx, y0, cz, sx, sy, sz, c)
		idx += 1
		-- tiny per-box size offset keeps overlapping faces from z-fighting
		local e = idx * 0.02
		block(m, origin, cx, y0 - e / 2, cz, V3(math.max(1, math.floor(sx)) + e, sy + e, math.max(1, math.floor(sz)) + e), c, "studs")
	end
	local layers = {
		{ w = width, h = 4, y = 0 },
		{ w = width * 0.78, h = 4, y = 3 },
		{ w = width * 0.5, h = 3, y = 6 },
	}
	-- one flat colour per clump (no shade variation)
	local c = Builder.pick(pal.Leaves, rng)
	leaf(0, -1, 0, width * 0.62, 2, width * 0.62, c)
	for _, L in layers do
		local lz = L.w * (0.8 + 0.3 * rng:NextNumber())
		leaf((rng:NextNumber() - 0.5) * 2, L.y, (rng:NextNumber() - 0.5) * 2, L.w, L.h, lz, c)
		for _ = 1, rng:NextInteger(2, 3) do
			local ox = (rng:NextNumber() - 0.5) * L.w * 0.9
			local oz = (rng:NextNumber() - 0.5) * L.w * 0.9
			local lw = L.w * (0.4 + 0.2 * rng:NextNumber())
			leaf(ox, L.y + rng:NextInteger(-1, 1), oz, lw, L.h, lw, c)
		end
	end
end

--------------------------------------------------------------------------------
-- Tree, after QM's reference: one thick flat-colour trunk, a couple of chunky
-- branches made of two angled segments with a leaf clump on each end, and a
-- crown of a few big, wide, flat slabs stacked and offset from each other.
-- One leaf colour per tree. opts: height, trunk (width), canopy (crown width),
-- branches, seed
--------------------------------------------------------------------------------
local function clump(m, origin: CFrame, c: Color3, rng: Random, w: number, idx: number)
	local e = idx * 0.03
	block(m, origin, 0, 0, 0, V3(w + e, math.max(4, math.floor(w * 0.7)) + e, math.floor(w * 0.9) + e), c, "studs")
	local w2 = math.max(3, math.floor(w * 0.6))
	block(m, origin, (rng:NextNumber() - 0.5) * w * 0.5, math.floor(w * 0.45), (rng:NextNumber() - 0.5) * w * 0.5, V3(w2 + e + 0.01, math.floor(w2 * 0.8) + e, w2 + e), c, "studs")
end

-- a straight segment from `start` (local space), heading `yaw` around Y and
-- tilted `tilt` radians off vertical; returns the far end
local function limb(m, origin: CFrame, start: Vector3, yaw: number, tilt: number, len: number, width: number, c: Color3): Vector3
	local d = V3(math.cos(yaw), 0, -math.sin(yaw))
	local axis = V3(0, math.cos(tilt), 0) + d * math.sin(tilt)
	local center = start + axis * (len / 2)
	local rot = CFrame.Angles(0, yaw, 0) * CFrame.Angles(0, 0, -tilt)
	Builder.part(m, V3(width, len + width * 0.5, width), origin * CFrame.new(center) * rot, c, "studs")
	return start + axis * len
end

function Kit.tree(parent, origin: CFrame, pal, opts)
	opts = opts or {}
	local rng = rngFor(opts)
	local H = opts.height or 28
	local tw = opts.trunk or math.max(4, math.floor(H / 5))
	local crown = opts.canopy or math.floor(H * 0.9)
	local leaf = Builder.pick(pal.Leaves, rng)
	local m = Builder.model(opts.name or "Tree", parent, origin)

	-- trunk: one thick block, a slightly wider foot
	block(m, origin, 0, 0, 0, V3(tw + 1, 1, tw + 1), pal.Trunk, "studs")
	block(m, origin, 0, 0, 0, V3(tw, H, tw), pal.Trunk, "studs")

	-- crown: big flat slabs, stacked and offset
	local idx = 0
	local function slab(x, y, z, w, h, d)
		idx += 1
		local e = idx * 0.03
		block(m, origin, x, y - e / 2, z, V3(math.floor(w) + e, h + e, math.floor(d) + e), leaf, "studs")
	end
	local top = H - 2
	slab(0, top - 3, 0, crown * 0.6, 3, crown * 0.55) -- underside
	slab((rng:NextNumber() - 0.5) * 4, top, (rng:NextNumber() - 0.5) * 4, crown, 6, crown * 0.85)
	local ang = rng:NextNumber() * math.pi * 2
	for i = 1, 2 do
		ang += math.pi * (0.7 + 0.6 * rng:NextNumber())
		local r = crown * (0.14 + 0.08 * rng:NextNumber())
		slab(math.cos(ang) * r, top + 1 + i * 4, math.sin(ang) * r, crown * (0.8 - i * 0.15), 5, crown * (0.7 - i * 0.12))
	end
	-- a loose block hanging off one corner, like the reference
	local ca = rng:NextNumber() * math.pi * 2
	slab(math.cos(ca) * crown * 0.42, top - 2, math.sin(ca) * crown * 0.42, crown * 0.3, 5, crown * 0.3)

	-- branches: two angled segments each, ending in a clump below the crown edge
	local count = math.min(opts.branches or 2, 4)
	local bw = math.max(2, math.floor(tw * 0.6))
	local yaw0 = rng:NextNumber() * math.pi * 2
	for b = 1, count do
		local yaw = yaw0 + (b - 1) * (math.pi * 2 / count) + (rng:NextNumber() - 0.5) * 0.6
		local hb = H * (0.3 + 0.12 * rng:NextNumber())
		local d = V3(math.cos(yaw), 0, -math.sin(yaw))
		local start = V3(0, hb, 0) + d * (tw / 2 - bw / 2)
		local mid = limb(m, origin, start, yaw, math.rad(50 + rng:NextNumber() * 12), math.max(5, crown * 0.32), bw, pal.Trunk)
		local tip = limb(m, origin, mid, yaw, math.rad(12 + rng:NextNumber() * 12), 3 + rng:NextInteger(0, 1), bw, pal.Trunk)
		clump(m, origin * CFrame.new(tip.X, tip.Y - 2, tip.Z), leaf, rng, math.max(6, math.floor(crown * 0.35)), b)
	end
	return m
end

return Kit

end

__modules["Lighting"] = function()
--[[
	Lighting: the bright, flat, low-contrast daylight look from the reference
	(crisp light shadows, no haze, no bloom, matte surfaces).
	Lighting.apply() sets the Lighting service and its post effects in place.
]]

local LightingService = game:GetService("Lighting")

local Lighting = {}

local function rgb(r: number, g: number, b: number): Color3
	return Color3.fromRGB(r, g, b)
end

-- Tuned in Studio against docs/reference (Nov 10): neutral grey ambient, equal
-- indoor and outdoor (trunks under a crown use Ambient), no sky tint on surfaces
-- (EnvironmentDiffuseScale 0), exposure 0 so the flat sky reads as in the reference.
-- Shadowed ground comes out about 77% of the lit ground, as there.
Lighting.Settings = {
	Technology = Enum.Technology.ShadowMap,
	Brightness = 1.4,
	ClockTime = 13,
	GeographicLatitude = 41.7,
	Ambient = rgb(225, 225, 225),
	OutdoorAmbient = rgb(225, 225, 225),
	ColorShift_Top = rgb(0, 0, 0),
	ColorShift_Bottom = rgb(0, 0, 0),
	GlobalShadows = true,
	ShadowSoftness = 0.2,
	EnvironmentDiffuseScale = 0,
	EnvironmentSpecularScale = 0, -- matte: no environment reflections
	ExposureCompensation = 0,
	FogStart = 100000,
	FogEnd = 100000,
}

Lighting.ColorCorrection = { Brightness = 0, Contrast = 0.05, Saturation = 0, TintColor = rgb(255, 255, 255) }

-- one flat sky colour, no sun, moon or stars
Lighting.SkyTexture = "rbxassetid://81588505365795"

local function child(className: string, name: string): Instance
	local c = LightingService:FindFirstChildOfClass(className)
	if not c then
		c = Instance.new(className)
		c.Name = name
		c.Parent = LightingService
	end
	return c
end

function Lighting.apply()
	for k, v in Lighting.Settings do
		pcall(function()
			(LightingService :: any)[k] = v
		end)
	end
	-- no haze, glow, god rays or blur: the reference reads clean and flat
	for _, c in LightingService:GetChildren() do
		if c:IsA("BloomEffect") or c:IsA("SunRaysEffect") or c:IsA("DepthOfFieldEffect") or c:IsA("BlurEffect") then
			c.Enabled = false
		elseif c:IsA("Atmosphere") then
			c.Density = 0
			c.Haze = 0
			c.Glare = 0
		end
	end
	local sky = child("Sky", "Sky") :: Sky
	for _, face in { "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp" } do
		(sky :: any)[face] = Lighting.SkyTexture
	end
	sky.CelestialBodiesShown = false
	sky.StarCount = 0
	local cc = child("ColorCorrectionEffect", "AssetKitColor") :: ColorCorrectionEffect
	for k, v in Lighting.ColorCorrection do
		(cc :: any)[k] = v
	end
	cc.Enabled = true
end

return Lighting

end

__modules["Palette"] = function()
--[[
	Palette: one colour set per biome.

	Every generator in Kit reads colours from a palette table, so a new biome is
	mostly a new entry here plus a list of assets in its own module.
]]

local function rgb(r: number, g: number, b: number): Color3
	return Color3.fromRGB(r, g, b)
end

local Palette = {}

-- Fallback settings for the native baseplate look. Normally the ground is a
